static unsigned checks;
static char directory[4096];
static void require(int ok,const char *message){checks++;if(!ok){fprintf(stderr,"foundation FAIL: %s\n",message);exit(1);}}
static char *dup_text(const char *s){char *p=malloc(strlen(s)+1);require(p!=NULL,"copy allocation");strcpy(p,s);return p;}
static void path(char out[4096],const char *name){require(snprintf(out,4096,"%s/%s",directory,name)<4096,"fixture path");}
static void save(const char *name,const char *data,size_t n){char p[4096];path(p,name);FILE *f=fopen(p,"wb");require(f&&fwrite(data,1,n,f)==n&&!fclose(f),"write owned fixture");}
static char *readall(const char *p){FILE *f=fopen(p,"rb");require(f!=NULL,"read fixture");require(!fseek(f,0,SEEK_END),"fixture seek");long n=ftell(f);require(n>=0&&n<12*1024*1024,"bounded fixture");rewind(f);char *s=calloc(1,(size_t)n+1);require(s&&fread(s,1,(size_t)n,f)==(size_t)n&&!fclose(f),"fixture read");return s;}
static char *run(char *const args[],const char *stdin_name,int expected_exit){char out[4096],in[4096];path(out,"response");if(stdin_name)path(in,stdin_name);fflush(NULL);pid_t pid=fork();require(pid>=0,"fork executable");if(!pid){alarm(20);if(!freopen(out,"wb",stdout)||(stdin_name&&!freopen(in,"rb",stdin)))_exit(126);execv(args[0],args);_exit(127);}int status;require(waitpid(pid,&status,0)==pid&&WIFEXITED(status)&&WEXITSTATUS(status)==expected_exit,"actual bounded exit");return readall(out);}
static void output(const char *response,const char *expected){ApxValue *actual=apx_json_parse(response,strlen(response));require(actual!=NULL,"response JSON");const char *status=apx_json_string(apx_json_get(actual,"status"));require(status&&!strcmp(status,"ok"),"successful native envelope");char *got=apx_json_encode(apx_json_get(actual,"output"));ApxValue *wanted=apx_json_parse(expected,strlen(expected));char *want=apx_json_encode(wanted);if(!got||!want||strcmp(got,want))fprintf(stderr,"got %s expected %s\n",got?got:"NULL",expected);require(got&&want&&!strcmp(got,want),"exact native result");free(got);free(want);apx_json_reset();}
static char *call(const char *source,const char *input,const char *policy){save("call.apx",source,strlen(source));save("input.json",input,strlen(input));char src[4096],inp[4096],pol[4096];path(src,"call.apx");path(inp,"input.json");path(pol,policy?policy:"policy.json");char *args[]={"bin/apodexis","run",src,"--input",inp,"--json",NULL,NULL,NULL};if(policy){args[6]="--capabilities";args[7]=pol;}return run(args,NULL,0);}
static void native_hosts(void){char root[4096];require(getcwd(root,sizeof root)!=NULL,"working directory");char abs[8192];require(snprintf(abs,sizeof abs,"%s/%s",root,directory)<8192,"absolute root");char policy[20000];snprintf(policy,sizeof policy,"{\"schema\":\"apodexis.host_policy.v1\",\"read_root\":\"%s\",\"write_root\":\"%s\",\"env\":[\"APX_FOUNDATION_FIXTURE\"],\"clock\":true,\"random\":true,\"max_requests\":64}",abs,abs);save("policy.json",policy,strlen(policy));require(!setenv("APX_FOUNDATION_FIXTURE","explicit-env",1),"fixture env");save("data.txt","real read",9);
 const char *read="M read\nF main->result str str\n  R (fs_read \"data.txt\")\n";char *r=call(read,"null",NULL);output(r,"{\"tag\":\"err\",\"error\":\"capability_denied\"}");free(r);r=call(read,"null","policy.json");output(r,"{\"tag\":\"ok\",\"value\":\"real read\"}");free(r);
 r=call("M write\nF main->result i64 str\n  R (fs_write \"saved.txt\" \"saved native value\")\n","null","policy.json");output(r,"{\"tag\":\"ok\",\"value\":18}");free(r);char p[4096];path(p,"saved.txt");r=readall(p);require(!strcmp(r,"saved native value"),"external write exact readback");free(r);
 r=call("M env\nF main->result str str\n  R (env_get \"APX_FOUNDATION_FIXTURE\")\n","null","policy.json");output(r,"{\"tag\":\"ok\",\"value\":\"explicit-env\"}");free(r);
 r=call("M env\nF main->result str str\n  R (env_get \"HOME\")\n","null","policy.json");output(r,"{\"tag\":\"err\",\"error\":\"environment_denied\"}");free(r);
 r=call("M clock\nF main->i64\n  L i 0\n  W (< i 64)\n    C (clock_ms)\n      ok time\n        S i (+ i 1)\n      err problem\n        R -1\n  R i\n","null","policy.json");output(r,"64");free(r);
 r=call("M random\nF main->i64\n  C (random_hex 16)\n    ok value\n      R (# value)\n    err problem\n      R -1\n","null","policy.json");output(r,"32");free(r);
 r=call("M bad\nF main->result str str\n  R (fs_read \"../outside\")\n","null","policy.json");output(r,"{\"tag\":\"err\",\"error\":\"filesystem_read_denied\"}");free(r);
 char *large=calloc(1,1048577);require(large!=NULL,"large UTF-8 fixture");save("controls",large,1048576);free(large);
 r=call("M controls\nF main->i64\n  C (fs_read \"controls\")\n    ok value\n      R (# value)\n    err problem\n      R -1\n","null","policy.json");output(r,"1048576");free(r);
 r=call("M continued\nF main->result str str\n  L first (fs_read \"controls\")\n  R (fs_read \"data.txt\")\n","null","policy.json");output(r,"{\"tag\":\"ok\",\"value\":\"real read\"}");free(r);
}
static void post_host_traps(void){
 const char *tails[]={"  R [1][2]\n","  A false\n  R 0\n","  Z \"after host\"\n","  R (/ 1 0)\n","  L out (buf i64 0)\n  P out 1\n  R 0\n","  L invalid (str_f64 (* 1e308 1e308))\n  R 0\n","  R 0\n"};
 const char *codes[]={"R103","X101","R999","R101","R301","R999","R201"};
 const int fuel[]={2,2,2,2,3,2,1};
 for(size_t i=0;i<7;i++){
  char source[2048];snprintf(source,sizeof source,"M after_host\nF main->i64\n  L observed (clock_ms)\n%s",tails[i]);save("trap.apx",source,strlen(source));char file[4096],policy[4096];path(file,"trap.apx");path(policy,"policy.json");
  for(int grant=0;grant<2;grant++){
   char *args[12]={"bin/apodexis","run",file,"--json",NULL};int count=4;if(grant){args[count++]="--capabilities";args[count++]=policy;}if(i==6){args[count++]="--fuel";args[count++]="1";}args[count]=NULL;
   char *r=run(args,NULL,2);ApxValue *v=apx_json_parse(r,strlen(r));const char *code=apx_json_string(apx_json_get(apx_json_get(v,"diagnostic"),"code"));if(!code||strcmp(code,codes[i]))fprintf(stderr,"post-host trap result: %s\n",r);require(code&&!strcmp(code,codes[i]),"post-host diagnostic preserved");require(apx_json_integer(apx_json_get(v,"fuel_used"))==fuel[i],"post-host fuel preserved");free(r);apx_json_reset();
  }
 }
}
static void modular_application(void){const char *input="{\"source\":\"report-input\",\"destination\":\"report-output\"}";save("input.json",input,strlen(input));save("report-input"," alpha,2\nbeta,3\nalpha,4\n",24);char inp[4096],pol[4096];path(inp,"input.json");path(pol,"policy.json");char *args[]={"bin/apodexis","run","examples/file_report/main.apx","--input",inp,"--capabilities",pol,"--json",NULL};char *r=run(args,NULL,0);output(r,"{\"tag\":\"ok\",\"value\":{\"counts\":{\"alpha\":6,\"beta\":3},\"total\":9,\"label\":\"written\"}}");free(r);char out[4096];path(out,"report-output");r=readall(out);require(!strcmp(r,"alpha,6\nbeta,3\n"),"multi-file report exact file readback");free(r);
 char *test[]={"bin/apodexis","test","examples/file_report/main.apx","--json",NULL};r=run(test,NULL,0);ApxValue *v=apx_json_parse(r,strlen(r));require(apx_json_length(apx_json_get(v,"tests"))==3,"root and imported tests execute");free(r);apx_json_reset();
}
static void mcp_bundle(void){const char *source="M app\nI u \"util\"\nF main->i64\n  R (u::answer)\n";const char *module="M util\nV answer\nF answer->i64\n  R 42\n";char *s=apx_json_encode(apx_string(source,(int64_t)strlen(source))),*m=apx_json_encode(apx_string(module,(int64_t)strlen(module)));char payload[10000];int n=snprintf(payload,sizeof payload,"{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\"}\n{\"jsonrpc\":\"2.0\",\"method\":\"notifications/initialized\"}\n{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/call\",\"params\":{\"name\":\"apodexis_bundle\",\"arguments\":{\"source\":%s,\"modules\":{\"util\":%s}}}}\n{\"jsonrpc\":\"2.0\",\"id\":3,\"method\":\"tools/call\",\"params\":{\"name\":\"apodexis_check\",\"arguments\":{\"source\":\"M holes\\nF main->map i64\\n  R _\\n\"}}}\n",s,m);require(n>0&&(size_t)n<sizeof payload,"MCP transcript bound");free(s);free(m);apx_json_reset();save("mcp-input",payload,(size_t)n);char *args[]={"bin/apx-mcp",NULL};char *all=run(args,"mcp-input",0);const char *cursor=all;char *assembled=NULL;while(*cursor){const char *end=strchr(cursor,'\n');require(end!=NULL,"MCP newline");ApxValue *v=apx_json_parse(cursor,(size_t)(end-cursor));require(v&&!apx_json_get(v,"error"),"MCP accepted response");int id=(int)apx_json_integer(apx_json_get(v,"id"));ApxValue *structured=apx_json_get(apx_json_get(v,"result"),"structuredContent");if(id==2){const char *text=apx_json_string(apx_json_get(structured,"source"));require(text&&strstr(text,"__apx_m1_answer"),"live bundle resolves exported function");assembled=dup_text(text);}if(id==3){ApxValue *hole=apx_json_item(apx_json_get(structured,"typed_holes"),0);const char *kind=apx_json_string(apx_json_get(apx_json_get(hole,"expected_type"),"kind"));require(kind&&!strcmp(kind,"map"),"MCP map type diagnostics match schema");}cursor=end+1;}require(assembled!=NULL,"bundle source provided");free(all);apx_json_reset();char *r=call(assembled,"null",NULL);output(r,"42");free(r);free(assembled);}
static int http_listener(unsigned *port){int fd=socket(AF_INET,SOCK_STREAM,0);require(fd>=0,"owned HTTP socket");struct sockaddr_in a={0};a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);require(!bind(fd,(struct sockaddr*)&a,sizeof a)&&!listen(fd,8),"loopback bind");socklen_t size=sizeof a;require(!getsockname(fd,(struct sockaddr*)&a,&size),"dynamic HTTP port");*port=ntohs(a.sin_port);return fd;}
static void http_fixture(void){unsigned port;int server=http_listener(&port);pid_t pid=fork();require(pid>=0,"HTTP fixture fork");if(!pid){alarm(20);const char *paths[]={"/ok","/redirect","/{one,two}","/badutf"};for(size_t i=0;i<4;i++){int c=accept(server,NULL,NULL);if(c<0)_exit(2);char req[8192]={0};size_t n=0;while(n<sizeof req-1){ssize_t k=read(c,req+n,sizeof req-1-n);if(k<=0)break;n+=(size_t)k;if(strstr(req,"\r\n\r\n"))break;}char first[256];snprintf(first,sizeof first,"GET %s HTTP/",paths[i]);if(strncmp(req,first,strlen(first)))_exit(3);const char *body=i==3?"\xff":"loopback body";char header[256];int len=snprintf(header,sizeof header,"HTTP/1.1 %s\r\nContent-Length: %zu\r\nLocation: /never\r\nConnection: close\r\n\r\n",i==1?"302 Found":"200 OK",strlen(body));if(write(c,header,(size_t)len)!=len||write(c,body,strlen(body))!=(ssize_t)strlen(body))_exit(4);close(c);}close(server);_exit(0);}close(server);char policy[2000];snprintf(policy,sizeof policy,"{\"schema\":\"apodexis.host_policy.v1\",\"http_get\":[\"http://127.0.0.1:%u/ok\",\"http://127.0.0.1:%u/redirect\",\"http://127.0.0.1:%u/{one,two}\",\"http://127.0.0.1:%u/badutf\"]}",port,port,port,port);save("http-policy.json",policy,strlen(policy));const char *paths[]={"/ok","/not-granted","/redirect","/{one,two}","/badutf"};const char *want[]={"{\"tag\":\"ok\",\"value\":\"loopback body\"}","{\"tag\":\"err\",\"error\":\"http_get_denied\"}","{\"tag\":\"err\",\"error\":\"http_get_failed\"}","{\"tag\":\"ok\",\"value\":\"loopback body\"}","{\"tag\":\"err\",\"error\":\"http_non_utf8\"}"};for(size_t i=0;i<5;i++){char src[1024];snprintf(src,sizeof src,"M http\nF main->result str str\n  R (http_get \"http://127.0.0.1:%u%s\")\n",port,paths[i]);char *r=call(src,"null","http-policy.json");output(r,want[i]);free(r);}int status;require(waitpid(pid,&status,0)==pid&&WIFEXITED(status)&&WEXITSTATUS(status)==0,"only granted exact HTTP requests observed; no redirects/glob expansion");}
int main(void){char template[]=".build/foundation-XXXXXX";char *d=mkdtemp(template);require(d!=NULL,"owned integration directory");strcpy(directory,d);native_hosts();post_host_traps();modular_application();mcp_bundle();http_fixture();DIR *entries=opendir(directory);require(entries!=NULL,"cleanup directory");struct dirent *entry;while((entry=readdir(entries))){if(!strcmp(entry->d_name,".")||!strcmp(entry->d_name,".."))continue;char p[4096];path(p,entry->d_name);require(!unlink(p),"owned fixture cleanup");}closedir(entries);require(!rmdir(directory),"no leftover integration files");apx_json_reset();printf("application foundation: %u checks; CLI imports, MCP bundle/maps, actual files/env/clock/entropy/HTTP and default denial PASS\n",checks);return 0;}
